function bind_target_query(frm) {

    frm.set_query("t_warehouse", "items", function(doc, cdt, cdn) {

        let row = locals[cdt][cdn];
        let entry_type = doc.stock_entry_type;  
        let from_wh = row.s_warehouse || doc.from_warehouse;
        if (!from_wh) return {};

        let section = get_section(from_wh);
        let store_type = get_store_type(from_wh);
        let material_type = get_material_type(from_wh);

        let filters = [];

        // Always same section
         if(entry_type != "Manufacture"){
                if (section) {
                    filters.push(["Warehouse", "name", "like", "%(" + section + ")%"]);
                }
         }

        // ===== MOVEMENT RULES =====

        if (store_type === "RECEIVING") {
           // filters.push(["Warehouse", "name", "like", "%Under Test Store%"]);
            filters.push(["Warehouse", "name", "in", [
                "RM Under Test Store - (" + section + ") - BS",
                "PM Under Test Store - (" + section + ") - BS",
                "FG FINAL PACKING - (" + section + ") - BS"
            ]]);
        }

        else if (store_type === "UNDER_TEST") {
            filters.push(["Warehouse", "name", "in", [
                material_type + " Approved Store - (" + section + ") - BS",
                material_type + " Reject Store - (" + section + ") - BS"
            ]]);
        }

        else if (store_type === "REJECT") {
            filters.push(["Warehouse", "name", "in", [
                material_type + " Under Test Store - (" + section + ") - BS",
                "Receiving Store - (" + section + ") - BS"
            ]]);
        }

        else if (store_type === "WIP") {
            if(entry_type === "Material Transfer") {

                filters.push(["Warehouse", "name", "in", [
                    "RM Approved Store - (" + section + ") - BS",
                    "PM Approved Store - (" + section + ") - BS",
                    "RM Under Test Store - (" + section + ") - BS",
                    "PM Under Test Store - (" + section + ") - BS"
                ]]);

            }else{
                 /*
                 filters.push(["Warehouse", "name", "in", [
                    "%(" + section + ")%",
                    "FG MAIN STORE - BS"
                ]]); 
                */
            }

            //filters.push(["Warehouse", "name", "like", "%Approved Store%"]);


        }

        else if (store_type === "APPROVED") {
         if(entry_type === "Material Transfer for Manufacture") {
            filters.push(["Warehouse", "name", "in", [
                "Work In Progress - (" + section + ") - BS"
               // material_type + " Reject Store - (" + section + ") - BS",
               // material_type + " Under Test Store - (" + section + ") - BS",
               // "Receiving Store - (" + section + ") - BS"
            ]]);
         }
        }

        return { filters: filters };
    });
}


function get_section(warehouse) {
    if (!warehouse) return null;
    if (warehouse.includes("(A)")) return "A";
    if (warehouse.includes("(B)")) return "B";
    if (warehouse.includes("(C)")) return "C";
    return null;
}

function get_store_type(warehouse) {
    if (!warehouse) return null;

    if (warehouse.includes("Receiving Store")) return "RECEIVING";
    if (warehouse.includes("Under Test Store")) return "UNDER_TEST";
    if (warehouse.includes("Approved Store")) return "APPROVED";
    if (warehouse.includes("Reject Store")) return "REJECT";
    if (warehouse.includes("Work In Progress")) return "WIP";

    return null;
}

function get_material_type(warehouse) {
    if (!warehouse) return null;

    if (warehouse.includes("RM")) return "RM";
    if (warehouse.includes("PM")) return "PM";

    return null;
}

function bind_parent_query(frm) {

    frm.set_query("to_warehouse", function(doc) {

        let from_wh = doc.from_warehouse;
        if (!from_wh) return {};

        let entry_type = doc.stock_entry_type;

        let section = get_section(from_wh);
        let store_type = get_store_type(from_wh);
        let material_type = get_material_type(from_wh);

        let filters = [];

        // Always same section
        if(entry_type != "Manufacture"){
        if (section) {
           filters.push(["Warehouse", "name", "like", "%(" + section + ")%"]);
        }
        }

        // =========================
        // STRICT MATRIX RULES
        // =========================

        if (store_type === "RECEIVING") {
            // Can go only to RM/PM Under Test of same section
           // FG FINAL PACKING - (A) - BS
           // filters.push(["Warehouse", "name", "like", "%Under Test Store%"]);
            filters.push(["Warehouse", "name", "in", [
                "RM Under Test Store - (" + section + ") - BS",
                "PM Under Test Store - (" + section + ") - BS",
                "FG FINAL PACKING - (" + section + ") - BS"
            ]]);
        }

        else if (store_type === "UNDER_TEST") {
            // RM Under Test → RM Approved / RM Reject
            // PM Under Test → PM Approved / PM Reject

            filters.push(["Warehouse", "name", "in", [
                material_type + " Approved Store - (" + section + ") - BS",
                material_type + " Reject Store - (" + section + ") - BS"
            ]]);
        }

        else if (store_type === "REJECT") {
            // Reject → Under Test OR Receiving (same section)

            filters.push(["Warehouse", "name", "in", [
                material_type + " Under Test Store - (" + section + ") - BS",
                "Receiving Store - (" + section + ") - BS"
            ]]);
        }

        else if (store_type === "WIP") {
            // WIP → Approved of same material + section
             if(entry_type === "Material Transfer") {

                filters.push(["Warehouse", "name", "in", [
                    "RM Approved Store - (" + section + ") - BS",
                    "PM Approved Store - (" + section + ") - BS",
                    "RM Under Test Store - (" + section + ") - BS",
                    "PM Under Test Store - (" + section + ") - BS"
                ]]); 

             }else if(entry_type === "Manufacture"){
               /*  
               filters.push(["Warehouse", "name", "in", [
                    "FG QUARANTINE - (" + section + ") - BS",
                    "FG MAIN STORE - BS"

                ]]); 
                */
            }

            //filters.push(["Warehouse", "name", "like", "%Approved Store%"]);
        }

        else if (store_type === "APPROVED") {

            if(entry_type === "Material Transfer for Manufacture") {
                filters.push(["Warehouse", "name", "in", [
                    "Work In Progress - (" + section + ") - BS"
                   // material_type + " Reject Store - (" + section + ") - BS",
                   // material_type + " Under Test Store - (" + section + ") - BS",
                   // "Receiving Store - (" + section + ") - BS"
                ]]);
             }
        }

        return { filters: filters };
    });
}


