    if (frm.doc.work_order) {

        frappe.db.get_value("Work Order", frm.doc.work_order, "custom_section")
            .then(r => {
                console.log("res:",r);
                if (r && r.message && r.message.custom_section) {
                    frm.set_value("custom_section", r.message.custom_section);
                }
            });

  }
}

