// ---------------- BATCH DETAILS ----------------

function fetch_batch_details(frm) {

    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Batch",
            name: frm.doc.manufacturing_batch
        },
        callback: function(r) {

            if (r.message) {

                let batch = r.message;

                frm.set_value('manufacturing_date', batch.manufacturing_date);
                frm.set_value('item', batch.item);

                // Expiry = +2 years
                if (batch.manufacturing_date) {
                    let mfg_date = frappe.datetime.str_to_obj(batch.manufacturing_date);
                    mfg_date.setFullYear(mfg_date.getFullYear() + 2);
                    let expiry = frappe.datetime.obj_to_str(mfg_date);

                    frm.set_value('expiry_date', expiry);
                }
            }
        }
    });
}


// ---------------- STOCK ENTRY DETAILS ----------------

function fetch_stock_entry_details(frm) {

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Stock Entry",
            filters: {
                docstatus: 1,
                stock_entry_type: "Manufacture",
                custom_final_batch: frm.doc.manufacturing_batch
            },
            fields: ["name"],
            limit_page_length: 1   // only latest matching entry
        },
        callback: function(res) {

            if (!res.message || res.message.length === 0) {
                frappe.msgprint("No Stock Entry found for this batch");
                return;
            }

            let stock_entry_name = res.message[0].name;

            // Fetch full Stock Entry
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Stock Entry",
                    name: stock_entry_name
                },
                callback: function(r) {

                    let se = r.message;

                    if (!se || !se.items) return;

                    se.items.forEach(item => {

                        // Only Finished Item
                        if (item.is_finished_item == 1) {

                            // Batch Size = Qty
                            frm.set_value("batch_size", item.qty || 200);

                            // No of Containers = Qty as per Stock UOM
                            frm.set_value("no_of_container", item.transfer_qty || 10);
                        }
                    });
                }
            });

        }
    });
}


