frappe.ui.form.on('Inner Container Label', {

   generate_containers(frm) {

        if (!frm.doc.batch_size || !frm.doc.no_of_container) {
            frappe.msgprint("Please enter Batch Size and No of Containers");
            return;
        }

        frm.clear_table("container_code_details");

        let count = frm.doc.no_of_container;
        let net_weight = frm.doc.batch_size / count;
        let used_codes = new Set();   // ✅ track unique codes
        for (let i = 0; i < count; i++) {

            let code;
            // 🔁 Keep generating until unique
            do {
              code = generate_random_code(4);
            } while (used_codes.has(code));
            used_codes.add(code);

            let row = frm.add_child("container_code_details");

            row.container_no = code;  // random
            row.net_weight = net_weight;
            row.tare_weight = 5;
            row.gross_weight = net_weight + 5;
        }

        frm.refresh_field("container_code_details");
    }
});


